svg.script:
{
  "metadata": {
    "title": "Business Process Model",
    "projectName": "Food Delivery System",
    "description": "Business process modeling with swimlanes and activities",
    "version": "1.0",
    "created": "2024-01-01T00:00:00Z",
    "mode": "light"
  },
  "config": {
    "layout": {"canvasWidth": 1920, "canvasHeight": 1080},
    "styling": {"mode": "light", "canvasColor": "#FFFFFF", "fillColor": "#E5E5E5", "strokeColor": "#1A1A1A", "cornerRadius": 8, "strokeWidth": 1.5}
  },
  "data": {
    "swimlanes": [
      {"id": "lane1", "name": "Lane 1", "x": 100, "y": 180, "width": 760, "height": 780},
      {"id": "lane2", "name": "Lane 2", "x": 900, "y": 180, "width": 760, "height": 780}
    ],
    "activities": [
      {"id": "action1", "name": "Action", "type": "activity", "x": 200, "y": 280, "width": 140, "height": 56},
      {"id": "decision1", "name": "Decision", "type": "decision", "x": 420, "y": 400, "width": 56, "height": 56},
      {"id": "merge1", "name": "Merge", "type": "merge", "x": 620, "y": 520, "width": 140, "height": 56}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#business-process-model-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[Business Process Model Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[Business Process Model] Invalid JSON:', e.message);
  }
})();
